mapper.select:
select 
  from sdsshop.u_p_purchase p
 where p.shop_code = #{shopCode}
   and p.purchasecode = #{purchaseCode}
 for update


where p.shop_code = #{shopCode}

  and p.purchasecode = #{purchaseCode}


  and p.partnercode = #{partnerCode}


  and p.partnername like concat('%', #{partnerName}, '%')




      and p.status in ('approved', 'partial_received')


      and p.status = #{status}



  and p.purchasedate = #{purchaseDate}


order by p.createtime desc, p.purchasecode desc


where p.shop_code = #{shopCode}
  and (

      p.purchasecode = #{includeCode} or

      (p.status <> 'draft' and coalesce(p.paidamount, 0) > 0)
  )
order by p.createtime desc, p.purchasecode desc

mapper.update:
update sdsshop.u_p_purchase
   set actualfreight = coalesce(actualfreight, 0) + #{amount},
       updatetime = sysdate()
 where shop_code = #{shopCode}
   and purchasecode = #{purchaseCode}

update sdsshop.u_p_purchase
set paidamount = greatest(coalesce(paidamount, 0) + #{amount}, 0),
paystatus = case when coalesce(paidamount, 0) <= 0 then '未支付' when coalesce(paidamount, 0) < coalesce(totalamount, 0) then '部分支付' when coalesce(paidamount, 0) = coalesce(totalamount, 0) then '已支付' else '超额支付' end, updatetime = sysdate() where shop_code = #{shopCode} and purchasecode = #{purchaseCode}

update sdsshop.u_p_purchase
   set status = #{status},
       updatetime = sysdate()
 where shop_code = #{shopCode}
   and purchasecode = #{purchaseCode}

